insert into public.football_team_profiles (team_id, nickname, tags, intro) values
(65, '시티즌스', '{맨체스터,에티하드 스타디움,1880년 창단}', $t$<p>맨체스터 시티는 2008년 아부다비 자본에 인수된 뒤 잉글랜드 축구의 판도를 바꾼 구단입니다. 펩 과르디올라 감독 체제에서 2020-21 시즌부터 4시즌 연속 리그 우승을 차지했고, 2022-23 시즌에는 리그·FA컵·챔피언스리그를 모두 들어 올리는 트레블을 달성했습니다. 같은 도시의 맨체스터 유나이티드와 치르는 맨체스터 더비는 프리미어리그에서 가장 주목받는 경기 가운데 하나입니다.</p><p>토리코리 관전 포인트: 시티의 경기는 점유율보다 "상대 진영에서 공을 얼마나 오래 갖고 있느냐"로 읽는 편이 정확합니다. 경기당 실점과 무실점 비율이 흔들리는 시기가 곧 시티의 위기 신호였던 경우가 많으니, 팀 분석의 수비 지표를 함께 보세요.</p>$t$),
(57, '거너스', '{북런던,에미레이츠 스타디움,1886년 창단}', $t$<p>아스널은 런던 남동부 울리치의 군수공장 노동자들이 만든 팀으로, "거너스(포병)"라는 별명도 여기서 나왔습니다. 2003-04 시즌 리그 38경기를 한 번도 지지 않은 "무패 우승"은 지금도 프리미어리그의 전설로 남아 있습니다. 2006년 하이버리를 떠나 에미레이츠 스타디움으로 옮겼고, 토트넘과의 북런던 더비는 잉글랜드에서 가장 뜨거운 라이벌전 가운데 하나입니다.</p><p>토리코리 관전 포인트: 최근 아스널은 세트피스로 만드는 골의 비중이 높은 팀으로 꼽힙니다. 공격이 막히는 경기에서도 코너킥 한 번으로 흐름을 바꿀 수 있어, 무득점 경기 비율이 낮게 유지되는지가 우승 경쟁의 열쇠입니다.</p>$t$),
(397, '시걸스', '{브라이턴,아멕스 스타디움,1901년 창단}', $t$<p>브라이턴 앤 호브 앨비언은 잉글랜드 남부 해안 도시 브라이턴을 연고로 하는 구단입니다. 한때 홈구장 없이 떠돌 만큼 어려운 시기를 보냈지만, 2011년 아멕스 스타디움을 열고 2017년 1부로 올라온 뒤 프리미어리그에 자리를 잡았습니다. 데이터 분석으로 저평가된 선수를 찾아 키운 뒤 비싸게 파는 운영 모델로 유명합니다.</p><p>토리코리 관전 포인트: 주전 선수가 자주 바뀌는데도 성적이 크게 떨어지지 않는 것이 브라이턴의 힘입니다. 경기당 득점이 높은 시즌에는 실점도 함께 높아지는 경향이 있어, 양팀 득점 비율이 높은 경기가 많은 팀으로 보면 좋습니다.</p>$t$),
(402, '비스', '{서런던,브렌트퍼드,1889년 창단}', $t$<p>브렌트퍼드는 서런던의 작은 구단으로, 2021년 74년 만에 1부 리그로 돌아온 뒤 빠르게 프리미어리그에 적응했습니다. 2020년 오래 쓰던 그리핀 파크를 떠나 새 경기장으로 옮겼고, 구단주가 도입한 통계 기반 선수 영입으로 적은 예산에도 경쟁력을 유지하고 있습니다.</p><p>토리코리 관전 포인트: 브렌트퍼드는 롱 스로인과 코너킥 같은 세트피스를 철저히 준비하는 팀으로 알려져 있습니다. 강팀을 상대로도 골을 넣을 수 있는 무기라 "무득점" 비율이 중위권 팀치고 낮게 나오는지 눈여겨보세요.</p>$t$),
(341, '화이츠', '{리즈,엘런드 로드,1919년 창단}', $t$<p>리즈 유나이티드는 요크셔 지방을 대표하는 구단입니다. 1960~70년대 돈 레비 감독 시절 잉글랜드 최강팀으로 군림했고, 1991-92 시즌에는 프리미어리그 출범 직전 마지막 1부 리그 우승을 차지했습니다. 이후 재정 위기로 3부 리그까지 떨어졌다가 2020년 마르셀로 비엘사 감독과 함께 1부로 돌아와 큰 화제가 됐습니다.</p><p>토리코리 관전 포인트: 엘런드 로드의 응원은 잉글랜드에서 손꼽히게 뜨거워, 리즈는 전통적으로 홈과 원정 성적 차이가 큰 팀입니다. 홈·원정 순위를 따로 비교해 보면 리즈의 색깔이 잘 드러납니다.</p>$t$),
(64, '레즈', '{리버풀,안필드,1892년 창단}', $t$<p>리버풀은 유러피언컵과 챔피언스리그를 여섯 번 들어 올린 잉글랜드 최고 명문 가운데 하나입니다. 경기 전 안필드에 울려 퍼지는 "You'll Never Walk Alone"은 세계 축구에서 가장 유명한 응원가로 꼽힙니다. 오랜 리그 우승 가뭄을 2019-20 시즌에 끝냈고, 2024-25 시즌에도 정상에 올랐습니다. 같은 도시 에버턴과의 머지사이드 더비는 120년이 넘는 역사를 갖고 있습니다.</p><p>토리코리 관전 포인트: 리버풀은 강한 전방 압박으로 상대 진영에서 공을 빼앗아 빠르게 마무리하는 경기가 많습니다. 후반 득점 비율이 높은 편이라, 전반을 뒤진 경기에서 얼마나 승점을 되찾는지(역전 승점)가 리버풀의 기세를 보여주는 지표입니다.</p>$t$),
(62, '토피스', '{리버풀,힐 디킨슨 스타디움,1878년 창단}', $t$<p>에버턴은 잉글랜드 1부 리그에서 가장 많은 시즌을 보낸 구단으로, 1888년 풋볼리그 창설 멤버이기도 합니다. 130년 넘게 쓰던 구디슨 파크를 떠나 2025-26 시즌부터 머지강변 브램리무어 부두에 지은 새 경기장을 홈으로 쓰고 있습니다. 리버풀과의 머지사이드 더비는 한 도시를 둘로 나누는 라이벌전입니다.</p><p>토리코리 관전 포인트: 에버턴은 전통적으로 조직적인 수비와 제공권을 앞세우는 팀입니다. 경기당 실점과 무실점 경기 수가 순위를 좌우하는 경우가 많아, 수비 지표가 좋은 시즌에는 중위권 이상을 노릴 수 있습니다.</p>$t$),
(322, '타이거스', '{헐,MKM 스타디움,1904년 창단}', $t$<p>헐 시티는 잉글랜드 동부 항구 도시 헐을 연고로 하며, 주황색과 검은색 줄무늬 유니폼 덕분에 "타이거스"라는 별명으로 불립니다. 2008년 구단 역사상 처음 1부 리그에 올랐고, 2014년에는 FA컵 결승까지 진출해 아스널과 연장 접전을 벌였습니다.</p><p>토리코리 관전 포인트: 1부와 2부를 오가며 단단한 팀을 만들어 온 헐 시티에게는 홈 경기 승점이 잔류의 기반입니다. 홈 경기당 승점과 원정 경기당 승점 차이를 보면 이번 시즌 버티는 힘을 가늠할 수 있습니다.</p>$t$),
(67, '맥파이스', '{뉴캐슬,세인트 제임스 파크,1892년 창단}', $t$<p>뉴캐슬 유나이티드는 잉글랜드 북동부의 열정적인 축구 도시를 대표하는 구단으로, 흑백 줄무늬 유니폼 때문에 "맥파이스(까치)"라고 불립니다. 2021년 사우디아라비아 국부펀드가 인수한 뒤 빠르게 상위권으로 올라섰고, 2025년 리그컵 우승으로 오랜 국내 대회 무관을 끝냈습니다. 선덜랜드와의 타인-위어 더비는 잉글랜드에서 가장 격렬한 더비로 꼽힙니다.</p><p>토리코리 관전 포인트: 5만 명이 넘는 관중이 채우는 세인트 제임스 파크는 원정팀이 가장 부담스러워하는 경기장 가운데 하나입니다. 뉴캐슬의 홈 무실점 경기 수를 원정과 비교해 보면 홈 이점의 크기가 드러납니다.</p>$t$),
(61, '블루스', '{런던,스탬퍼드 브리지,1905년 창단}', $t$<p>첼시는 서런던 스탬퍼드 브리지를 홈으로 하는 구단으로, 2003년 로만 아브라모비치 인수 이후 잉글랜드와 유럽 무대의 강자로 떠올랐습니다. 2012년과 2021년 두 차례 챔피언스리그 정상에 올랐고, 2022년 새 소유주로 바뀐 뒤에는 젊은 선수를 대거 영입해 장기 계약으로 묶는 독특한 운영을 하고 있습니다. 2025년에는 컨퍼런스리그와 FIFA 클럽 월드컵을 연달아 우승했습니다.</p><p>토리코리 관전 포인트: 선수단이 젊은 만큼 경기마다 기복이 큰 편입니다. 첼시의 최근 5경기 폼과 시즌 전체 경기당 승점을 나란히 보면, 지금이 상승세인지 일시적인 반등인지 구분하는 데 도움이 됩니다.</p>$t$),
(349, '트랙터 보이스', '{입스위치,포트먼 로드,1878년 창단}', $t$<p>입스위치 타운은 잉글랜드 동부 서퍽 지방의 구단으로, 농업 지대라는 지역색 때문에 "트랙터 보이스"라는 별명을 얻었습니다. 1961-62 시즌 1부 리그 승격 첫해에 우승을 차지한 이변의 주인공이며, 당시 감독 알프 램지는 이후 잉글랜드를 1966 월드컵 우승으로 이끌었습니다. 1981년에는 보비 롭슨 감독과 함께 UEFA컵을 들어 올렸습니다.</p><p>토리코리 관전 포인트: 오랜 하부리그 생활 끝에 1부 무대를 밟은 팀들은 대개 원정에서 고전합니다. 입스위치가 원정에서 얼마나 승점을 챙기는지가 잔류 경쟁의 가장 현실적인 지표입니다.</p>$t$),
(66, '레드 데블스', '{맨체스터,올드 트래퍼드,1878년 창단}', $t$<p>맨체스터 유나이티드는 잉글랜드 1부 리그 우승을 20번 차지한 최다 우승 구단 가운데 하나입니다. 알렉스 퍼거슨 감독이 26년 넘게 이끌며 프리미어리그 13회 우승과 1999년 트레블을 이뤘고, 1958년 뮌헨 항공 참사를 딛고 일어선 역사도 구단 정체성의 중요한 부분입니다. 홈구장 올드 트래퍼드는 "꿈의 극장"으로 불립니다.</p><p>토리코리 관전 포인트: 퍼거슨 은퇴 이후 감독이 자주 바뀌며 리그 우승과는 거리가 멀어졌습니다. 맨유를 볼 때는 순위보다 골득실을 먼저 보길 권합니다. 승점에 비해 골득실이 작다면 접전을 운 좋게 이긴 경기가 많았다는 뜻입니다.</p>$t$),
(351, '포리스트', '{노팅엄,시티 그라운드,1865년 창단}', $t$<p>노팅엄 포리스트는 1865년 창단한 잉글랜드에서 가장 오래된 프로 구단 가운데 하나입니다. 브라이언 클러프 감독 시절인 1977-78 시즌 승격 첫해 리그 우승을 차지했고, 1979년과 1980년 유러피언컵을 2연패하는 기적을 썼습니다. 리그 우승 횟수보다 유럽 챔피언 횟수가 더 많은 독특한 기록을 가진 팀입니다.</p><p>토리코리 관전 포인트: 포리스트는 공 점유율을 내주고 빠른 역습으로 승부하는 경기가 많습니다. 점유율이 낮아도 이길 수 있는 팀이라, 경기당 득점보다 실점 지표가 성적을 더 잘 설명합니다.</p>$t$),
(71, '블랙 캣츠', '{선덜랜드,스타디움 오브 라이트,1879년 창단}', $t$<p>선덜랜드는 잉글랜드 북동부의 전통 구단으로, 1부 리그 우승을 여섯 차례 차지한 역사를 갖고 있습니다. 2010년대 후반 3부 리그까지 떨어지는 과정을 담은 다큐멘터리 "선덜랜드 틸 아이 다이"로 세계적으로 이름이 알려졌고, 2025년 프리미어리그로 돌아왔습니다. 뉴캐슬과의 타인-위어 더비는 지역의 자존심이 걸린 경기입니다.</p><p>토리코리 관전 포인트: 오래 기다린 1부 무대인 만큼 홈 관중의 응원이 큰 힘이 됩니다. 선덜랜드는 홈 경기당 승점이 원정보다 크게 높은지, 그리고 강팀을 상대로 무실점 경기를 만들어 내는지를 보면 잔류 가능성을 가늠할 수 있습니다.</p>$t$),
(354, '이글스', '{런던,셀허스트 파크,1905년 창단}', $t$<p>크리스털 팰리스는 남런던을 연고로 하는 구단으로, 1851년 만국박람회가 열렸던 수정궁(크리스털 팰리스)에서 이름을 따왔습니다. 2025년 FA컵 결승에서 맨체스터 시티를 꺾고 구단 역사상 첫 주요 대회 우승을 차지했습니다. 셀허스트 파크는 작지만 응원 열기가 뜨겁기로 유명합니다.</p><p>토리코리 관전 포인트: 팰리스는 빠른 측면 공격수를 활용한 역습이 강점인 팀입니다. 강팀과의 원정 경기에서 오히려 결과가 좋은 경우가 있어, 홈·원정 경기당 승점이 뒤집혀 있는지 확인해 보는 재미가 있습니다.</p>$t$),
(58, '빌런스', '{버밍엄,빌라 파크,1874년 창단}', $t$<p>애스턴 빌라는 1888년 세계 최초의 축구 리그인 풋볼리그를 만드는 데 앞장선 구단입니다. 1981-82 시즌 유러피언컵에서 바이에른 뮌헨을 꺾고 유럽 정상에 올랐으며, 잉글랜드 중부 버밍엄을 대표하는 팀입니다. 최근에는 챔피언스리그 무대에 복귀하며 다시 상위권 구단으로 자리 잡았습니다.</p><p>토리코리 관전 포인트: 빌라는 수비 라인을 높이 올려 상대 공격수를 오프사이드에 자주 빠뜨리는 운영으로 알려져 있습니다. 이런 팀은 강팀과의 경기에서 뒷공간을 한 번에 내주기도 해, 대량 실점 경기가 있었는지 함께 살펴보면 좋습니다.</p>$t$),
(1044, '체리스', '{본머스,바이탈리티 스타디움,1899년 창단}', $t$<p>AFC 본머스는 잉글랜드 남부 해안 휴양 도시를 연고로 하는 구단입니다. 2008년 파산 위기로 4부 리그에서 승점 삭감까지 받았지만, 불과 7년 만인 2015년 1부 리그에 올라 잉글랜드 축구의 대표적인 성공 스토리가 됐습니다. 홈구장은 1만 명 남짓한 작은 경기장입니다.</p><p>토리코리 관전 포인트: 본머스는 적극적인 전방 압박으로 많이 뛰는 축구를 합니다. 이런 스타일은 경기 막판 체력이 떨어질 때 실점이 늘기 쉬워, 전반과 후반 실점 차이를 보면 팀의 현재 상태가 잘 드러납니다.</p>$t$),
(1076, '스카이 블루스', '{코번트리,잉글랜드 중부,1883년 창단}', $t$<p>코번트리 시티는 잉글랜드 중부 도시 코번트리의 구단으로, 1967년부터 2001년까지 34년 동안 1부 리그에 머물렀고 1987년 FA컵 우승을 차지했습니다. 2001년 강등 이후 재정 문제와 홈구장 분쟁으로 4부 리그까지 떨어지는 긴 암흑기를 보냈습니다.</p><p>토리코리 관전 포인트: 긴 하부리그 생활을 거쳐 올라온 팀에게 1부 리그의 첫 시즌은 경험과의 싸움입니다. 코번트리의 경우 무득점 경기 비율이 얼마나 빨리 줄어드는지가 잔류 가능성을 보여주는 가장 중요한 숫자입니다.</p>$t$),
(63, '코티저스', '{런던,크레이븐 코티지,1879년 창단}', $t$<p>풀럼은 런던에서 가장 오래된 프로 축구 구단으로, 템스강변에 자리한 크레이븐 코티지를 홈으로 씁니다. 경기장 한쪽 모퉁이에 남아 있는 옛 오두막(코티지)이 이름의 유래입니다. 2010년에는 유로파리그 결승까지 올라 구단 역사상 최고의 성과를 냈습니다.</p><p>토리코리 관전 포인트: 풀럼은 중위권에서 안정적인 성적을 내는 해가 많지만, 시즌 중반 부진이 길어지면 강등권으로 빠르게 미끄러지기도 합니다. 최근 5경기 폼과 무승 기록을 함께 보면 흐름이 꺾이는 시점을 일찍 알아챌 수 있습니다.</p>$t$),
(73, '스퍼스', '{북런던,토트넘 홋스퍼 스타디움,1882년 창단}', $t$<p>토트넘 홋스퍼는 북런던을 연고로 하는 구단으로, 1960-61 시즌 20세기 잉글랜드 최초의 리그·FA컵 더블을 달성했습니다. 2015년부터 2025년까지 손흥민이 활약하며 한국 팬들에게 가장 친숙한 프리미어리그 구단이 됐고, 손흥민은 2021-22 시즌 득점왕에 올랐습니다. 2025년 유로파리그 우승으로 17년 만에 주요 대회 트로피를 들어 올렸습니다.</p><p>토리코리 관전 포인트: 토트넘은 공격적인 운영 탓에 득점과 실점이 모두 많은 경기가 자주 나옵니다. 2.5골 오버와 양팀 득점 비율이 리그 평균보다 높은지 살펴보면 팀의 경기 성향을 한눈에 알 수 있습니다.</p>$t$)
